window.HH_LIB["azzawi"]={"id":"azzawi","title":"القواعد الذهبية لتعلم الانكليزية","sub":"Golden Grammar","author":"عبد السلام العزاوي","coauthors":[],"translator":"","publisher":"","year":"","edition":"الطبعة الثانية، مزيدة ومنقحة","series":"","lead":"مرجع مبسط في قواعد اللغة الإنجليزية بشرح عربي وأمثلة إنجليزية، يبدأ بأجزاء الكلام وينتهي بالأزمنة والمبني للمجهول والكلام المنقول وملاحق للأفعال الشاذة والإملاء والمرادفات. يقول المؤلف إن الكتاب «مخصص بالدرجة الاساس للطالب بالمستوى المتوسط» وإنه «لبساطته يصلح لكافة المستويات».","audience":"طلاب المرحلتين المتوسطة والثانوية، ومعلمو اللغة الإنجليزية، والمتعلم الذاتي","bio":"","chapters":[{"k":"c1","t":"أجزاء الكلام والاسم Noun والإضافات Affixes","q":"كيف نعرف الاسم ونجمعه ونبني منه كلمات جديدة؟","essence":"الاسم: جمعه وعدّه وتركيبه واشتقاقه","kw":["المفرد والجمع","المعدود وغير المعدود","البواديء واللواحق"],"sections":[{"t":"أجزاء الكلام Parts of Speech","pg":5,"key":"تتكون الجملة في اللغة الانكليزية من 8 انواع من الكلمات","p":["يأتي الاسم غالبا قبل الفعل: Children play."],"items":[{"h":"الأنواع الثمانية","x":"Noun الاسم، Verb الفعل، Adjective الصفة، Adverb الظرف، pronoun الضمير، Conjunction اداة الربط، interjection صيغة التعجب، preposition حرف الجر."},{"h":"الاسم بعد المحددات","x":"يأتي الاسم بعد أدوات مثل a, the, some, his: The dog barked."},{"h":"الاسم بعد الصفة","x":"The angry dog barked."},{"h":"الاسم بعد حرف الجر","x":"She keeps papers in boxes."}]},{"t":"المفرد والجمع Singular and Plural","pg":6,"key":"تجمع معظم الاسماء في الانكليزية باضافة s أو es الى نهاية الكلمة","p":["وهناك اسماء شاذة (irregular) لاتنطبق عليها قاعدة معينة"],"items":[{"h":"إضافة es","x":"تضاف إلى الاسم المنتهي بأحد الحروف s، z، ch، sh، x: box boxes، dish dishes."},{"h":"الاسم المنتهي ب y بعد حرف ساكن","x":"تحذف y وتضاف ies: a city cities، a baby babies."},{"h":"أسماء شاذة","x":"woman women، child children، tooth teeth، foot feet، leaf leaves."},{"h":"صيغة واحدة للمفرد والجمع","x":"sheep sheep، fish fish، species species، aircraft aircraft."},{"h":"جمع بفعل مفرد","x":"The news is on at 6.30 p.m. / Athletics is good for young people."},{"h":"جمع بفعل جمع","x":"My trousers are too tight. / Her jeans are black."}]},{"t":"الاسماء المعدودة وغير المعدودة Countable & Uncountable Nouns","pg":8,"key":"وهذه الاسماء تكون غالبا اسماء لافكار مجردة أو صفات","p":["هناك بعض الاسماء (معدودة) في لغات أخرى ولكنها في الانكليزية تعتبر اسماء (غير معدودة)"],"items":[{"h":"المعدود","x":"له صيغة مفرد وجمع: two dogs, ten horses, a few ideas."},{"h":"غير المعدود","x":"يستخدم مع فعل مفرد ولا جمع له غالبا: tea, sugar, water, knowledge, beauty."},{"h":"التعبير عن الكمية","x":"لا تستخدم a/an، بل some, a lot of, a piece of, a great deal of: He gave me a great deal of advice before my interview."},{"h":"أسماء غير معدودة شائعة","x":"news, advice, furniture, information, luggage, progress, traffic, weather, work."},{"h":"كلمة hair","x":"غير معدودة عادة: Nada has long blonde hair. ومعدودة للشعرات المنفردة: Ahmed's getting a few grey hairs now."}]},{"t":"الاسماء المركبة Compound Nouns","pg":10,"key":"يمكن للكلمات ان تتوحد لتشكيل (اسماء مركبة)، وهذا شائع جدا","p":["يكون للاسماء المركبة غالبا معنى مختلف عن الكلمات المنفصلة"],"items":[{"h":"طرق الكتابة","x":"كلمة واحدة مثل policeman، أو كلمتان بشرطة مثل dining-table، أو كلمتان منفصلتان مثل fish tank."},{"h":"تراكيبها","x":"noun + noun: bedroom، verb + noun: swimming pool، adjective + noun: greenhouse."},{"h":"الشدة في النطق","x":"تقع غالبا على المقطع الأول: a 'greenhouse مكان لزراعة النباتات، و a green 'house بيت مصبوغ بالأخضر."},{"h":"من الأفعال المركبة","x":"breakdown, outcome, feedback, takeaway."}]},{"t":"البواديء واللواحق Prefixes & suffixes","pg":111,"key":"ان اضافة بعض الاحرف الى اصل الكلمة يؤدي الى تكوين كلمات جديدة ذات معنى مختلف","p":["البواديء (prefixes) عادة لاتغير صنف الكلمة الاصل، ولكن اللواحق (suffixes) عادة تغير صنف الكلمة"],"items":[{"h":"بواديء الأفعال","x":"re بمعنى again or back: rebuild، و dis تعكس المعنى: disappear، و mis بمعنى badly or wrongly: misinform."},{"h":"لواحق تكوّن أفعالا","x":"ise: symbolise، ate: duplicate، fy: simplify، en: shorten."},{"h":"لواحق تكوّن أسماء","x":"tion: demonstration، ment: punishment، ness: darkness، ship: friendship."},{"h":"لواحق تكوّن صفات","x":"ful: careful، less: careless، ous: dangerous، able: countable."},{"h":"بواديء النفي في الصفات","x":"unfortunate, impatient, illegal, dishonest, non-fiction."}]}],"quiz":[{"q":"Choose the correct plural: one child, two ...","o":["two children","two childs","two childes","two childrens"],"why":"وهناك اسماء شاذة (irregular) لاتنطبق عليها قاعدة معينة","pg":6},{"q":"Choose the correct sentence.","o":["The news is on at 6.30 p.m.","The news are on at 6.30 p.m.","The news were on at 6.30 p.m.","The newses are on at 6.30 p.m."],"why":"وأخرى بصيغة الجمع ولكنها تأخذ فعل مفرد","pg":7},{"q":"Complete: He gave me ... before my interview.","o":["a great deal of advice","a great many advices","a large number of advices","a few useful advices"],"why":"لايمكن استخدام ادوات النكرة a/an مع هذه الاسماء، وللتعبير عن مقدار أو كمية احدى هذه الاسماء، ويمكن استخدام بعض الكلمات أو التعبيرات","pg":9},{"q":"بماذا يتميز نطق الاسم المركب greenhouse من نطق green house المكونة من صفة واسم؟","o":["بوقوع الشدة على المقطع الأول","بوقوع الشدة على المقطع الأخير","بكتابة الجزأين متصلين بشرطة","بنطق الجزأين بشدة متساوية"],"why":"وتقع الشدة في الاسماء المركبة عادة على المقطع الاول","pg":12},{"q":"أي العبارات أدق في وصف أثر البواديء واللواحق في صنف الكلمة؟","o":["اللواحق تغيره عادة والبواديء لا تغيره","البواديء تغيره عادة واللواحق لا تغيره","كلاهما يغيره دائما مع تغيير معناها أيضا","كلاهما يبقيه ويغير المعنى إلى الضد"],"why":"البواديء (prefixes) عادة لاتغير صنف الكلمة الاصل، ولكن اللواحق (suffixes) عادة تغير صنف الكلمة","pg":111}]},{"k":"c2","t":"الفعل Verb: المصدر والأفعال المساعدة والناقصة","q":"متى يأتي المصدر مع to أو بدونها، وكيف تعمل الأفعال المساعدة والناقصة؟","essence":"المصدر والأفعال المساعدة والناقصة","kw":["المصدر","الأفعال المساعدة","الأفعال الناقصة"],"sections":[{"t":"المصدر The Infinitive","pg":13,"key":"المصدر هو الصيغة الاساسية للفعل","p":["يعبر عن نشاط (run, call, argue) او حالة (be, seem, become)"],"items":[{"h":"مع to بعد أفعال معينة","x":"want, wish, agree, fail, decide, learn: The elephant decided to marry the mouse."},{"h":"بعد to be to و to have to و ought to","x":"You will have to ask her. / He ought to relax."},{"h":"في النموذج it is + adjective + to-infinitive","x":"It's easy to speak English."}]},{"t":"المصدر بدون to","pg":14,"key":"يستخدم فقط عند الاشارة الى افعال المتحدث الخاصة","p":["لاحظ ان المصدر مع to يستخدم عندما يكون الفعل make في المبني للمجهول"],"items":[{"h":"بعد معظم الأفعال المساعدة","x":"She can't speak to you. / They must leave before 10.00 a.m."},{"h":"بعد أفعال الإدراك والحواس","x":"verb + object + zero infinitive: We heard them close the door."},{"h":"بعد make و let","x":"make/let + object + zero infinitive: Her parents let her stay out late."},{"h":"make في المبني للمجهول","x":"I am made to sweep the floor every day."},{"h":"بعد had better و would rather","x":"We had better take some warm clothing. / I would rather visit Rome."}]},{"t":"المصدر المنفي ووظائف المصدر","pg":16,"key":"لصياغة المصدر المنفي، نضع not قبل to أو قبل المصدر بدون to","p":["هذه الافعال ask, decide, explain, forget, know, show, tell, understand, يمكن ان تتبع بأداة استفهام (سؤال) مثل where, how, what, who, when أو whether متبوعة بمصدر مع to"],"items":[{"h":"النفي","x":"I decided not to go to London. / I'd rather not eat meat."},{"h":"بعد أدوات الاستفهام","x":"Do you understand what to do?"},{"h":"why في الاقتراحات بدون to","x":"Why not ask him now?"},{"h":"الغرض من العمل","x":"She's gone to collect her pay cheque."},{"h":"مع too و enough","x":"This soup is too hot to eat. / She's old enough to make up her own mind."}]},{"t":"الافعال المساعدة Auxiliary (helping) verbs","pg":21,"key":"ويستخدم عادة في النفي والاستفهام","p":["ويعبر عن كينونة الشيء"],"items":[{"h":"فعل الكينونة to be","x":"am, is, are في المضارع و was, were في الماضي: He is a teacher."},{"h":"فعل العمل to do","x":"do, does و did: Does he live in Dubai?"},{"h":"فعل التملك to have","x":"have, has و had، ويستخدم للتعبير عن الملكية: Sami has a car."}]},{"t":"الافعال الناقصة Modals","pg":23,"key":"يتبعها مصدر مجرد بدون to","p":["لاتستخدم do في الجمل الاستفهامية والمنفية"],"items":[{"h":"قائمتها","x":"can, could, may, might, will, would, shall, should, must, ought to."},{"h":"لا تلحقها إضافات","x":"He can speak French. ولا نقول He cans speak French."},{"h":"السؤال والنفي","x":"Can you remember her name? / We must not be late."},{"h":"من وظائفها","x":"can للقدرة، may لطلب الإذن، must للضرورة والإلزام، shall للعرض والاقتراح، should للنصيحة."},{"h":"الاختصارات","x":"cannot تصبح can't، will not تصبح won't، shall not تصبح shan't."}]}],"quiz":[{"q":"Choose the correct sentence.","o":["You must pay now.","You must to pay now.","You must paying now.","You musts pay now."],"why":"يتبعها مصدر مجرد بدون to","pg":23},{"q":"Choose the correct sentence.","o":["Her parents let her stay out late.","Her parents let her to stay out late.","Her parents let her staying out late.","Her parents let her stays out late."],"why":"make/let + object + zero infinitive","pg":14},{"q":"Choose the correct passive form.","o":["I am made to sweep the floor every day.","I am made sweep the floor every day.","I am made to sweeping the floor every day.","I am made swept the floor every day."],"why":"لاحظ ان المصدر مع to يستخدم عندما يكون الفعل make في المبني للمجهول","pg":15},{"q":"لماذا لا يصح أن نقول Do you can remember her name?","o":["لأن الأفعال الناقصة لا تأخذ do في السؤال","لأن can لا تستعمل في الجمل الاستفهامية","لأن do تأتي بعد الفاعل لا قبله في كل سؤال","لأن remember لا تتبع الأفعال الناقصة"],"why":"لاتستخدم do في الجمل الاستفهامية والمنفية","pg":23},{"q":"بحسب جدول الأفعال الناقصة، ماذا تفيد shall في السؤال Shall I help you with your luggage?","o":["تقديم عرض للمساعدة","طلب الإذن من المخاطب","التعبير عن الإلزام","التنبؤ غير الأكيد"],"why":"Shall I help you with your luggage? Offer العرض","pg":26}]},{"k":"c3","t":"الصفة Adjective والمقارنة بين الصفات","q":"أين تقع الصفة، وكيف نرتبها ونقارن بها؟","essence":"موقع الصفة وترتيبها ودرجات المقارنة","kw":["ترتيب الصفات","المقارنة والتفضيل","الصفات الشاذة"],"sections":[{"t":"موقع الصفة","pg":27,"key":"تاتي الصفة غالبا قبل الاسم","p":["انتبه لهذه الصفات، لان معناها سيختلف عند استخدامها قبل الاسم"],"items":[{"h":"قبل الاسم","x":"The black dog barked."},{"h":"مع الأفعال الوصفية","x":"feel, be, look, taste, seem: You look tired."},{"h":"بعد الاسم مع الأفعال السببية","x":"She made her brother angry."},{"h":"صفات تتغير دلالتها","x":"the people concerned أصحاب الشأن، و A concerned father أب قلق."}]},{"t":"شكل الصفات ووظيفتها","pg":28,"key":"لاتغير الصفات شكلها حسب جنس أو عدد الاسم","p":[],"items":[{"h":"ثبات الشكل","x":"A hot potato, Some hot potatoes."},{"h":"التقوية","x":"نستخدم very أو really: Some really hot potatoes."},{"h":"الجنسية أو المنشأ","x":"Pierre is French."},{"h":"الحكم والتقييم","x":"A fantastic film. / Grammar is boring."}]},{"t":"ترتيب الصفات","pg":29,"key":"عند استخدام عدد من الصفات سوية، فترتيبها يعتمد على وظيفة الصفة نفسها","p":["Value/opinion, Size, Age/Temperature, Shape, Colour, Origin, Material"],"items":[{"h":"أمثلة الكتاب","x":"a lovely old red post-box / some small round plastic tables / some charming small silver ornaments."}]},{"t":"المقارنة بين الصفات Comparison of Adjectives","pg":30,"key":"نستخدم صيغة المقارنة (comparative) عندما نقارن بين شخص و آخر أو شيء و آخر","p":["نستخدم more / most مع جميع الصفات المتكونة من مقطعين أو أكثر"],"items":[{"h":"الصفات ذات المقطع الواحد","x":"clean cleaner cleanest، cheap cheaper cheapest."},{"h":"ذات المقطعين المنتهية ب y","x":"happy happier happiest، easy easier easiest."},{"h":"مضاعفة الحرف الأخير","x":"big bigger biggest، sad sadder saddest."},{"h":"مثال الكتاب","x":"A cat is fast, a tiger is faster but a cheetah is the fastest."},{"h":"المقارنة ب than","x":"A car is more expensive than a bicycle."},{"h":"صفات بمعان مختلفة","x":"farther للمسافة و further للمسافة أو الزمن، older للأشخاص والأشياء و elder للأشخاص في العائلة."}]},{"t":"الصفات الشاذة والمقادير","pg":34,"key":"وهي الصفات التي لاتنطبق عليها قاعدة معينة بل يجب حفظها","p":["نستخدم fewer (تعني: أقل) مع الاسماء المعدودة","نستخدم less (تعني: أقل) مع الاسماء الغير معدودة"],"items":[{"h":"الشاذة","x":"good better best، bad worse worst، little less least."},{"h":"التشابه في المقادير","x":"They have as many children as us. / Hashim eats as much food as Murad."},{"h":"الاختلاف في المقادير","x":"Nadia has fewer children than Suha. / Nadia has less money than Suha."},{"h":"التشابه في الصفات as + adj + as","x":"Rana is as happy as Rasha."},{"h":"الاختلاف not so / as adj + as","x":"Norway is not as sunny as Thailand."}]}],"quiz":[{"q":"Choose the correct order of adjectives.","o":["a lovely old red post-box","a red old lovely post-box","an old lovely red post-box","a lovely red old post-box"],"why":"Value/opinion, Size, Age/Temperature, Shape, Colour, Origin, Material","pg":29},{"q":"Choose the correct sentence.","o":["Nadia has less money than Suha.","Nadia has fewer money than Suha.","Nadia has least money than Suha.","Nadia has lesser money than Suha."],"why":"نستخدم less (تعني: أقل) مع الاسماء الغير معدودة","pg":36},{"q":"بحسب القاعدة العامة في الكتاب، مع أي الصفات نستخدم more و most؟","o":["الصفات المتكونة من مقطعين أو أكثر","الصفات ذات المقطع الواحد بلا استثناء","الصفات المنتهية بحرف y جميعها","الصفات الشاذة مثل good و bad"],"why":"نستخدم more / most مع جميع الصفات المتكونة من مقطعين أو أكثر","pg":32},{"q":"لماذا ينبه الكتاب على صفات مثل involved و concerned و present؟","o":["لأن معناها يختلف إذا جاءت قبل الاسم","لأنها لا تأتي إلا قبل الاسم مباشرة","لأن شكلها يتغير بحسب جنس الاسم وعدده","لأنها لا تقبل صيغة المقارنة أبدا"],"why":"انتبه لهذه الصفات، لان معناها سيختلف عند استخدامها قبل الاسم","pg":27},{"q":"متى نستخدم elder و eldest بدلا من older و oldest؟","o":["للأشخاص في العائلة","للأشخاص والأشياء معا","للمسافة أو الزمن","للترتيب بين الأشياء"],"why":"elder eldest (للاشخاص في العائلة)","pg":33}]},{"k":"c4","t":"الظرف Adverb","q":"كيف نصوغ الظرف، وأين نضعه في الجملة؟","essence":"صياغة الظرف وأنواعه ومواقعه","kw":["صياغة الظرف","موقع الظرف","ظروف التكرار"],"sections":[{"t":"تعريف الظرف وموقعه","pg":37,"key":"يصف الفعل أو الصفة أو ظرف آخر أو كل الجملة","p":[],"items":[{"h":"بعد الفعل","x":"Huda walked slowly."},{"h":"قبل الصفة","x":"The box was extremely heavy."},{"h":"قبل ظرف آخر","x":"She talked very quietly."},{"h":"في بداية الجملة","x":"Unfortunately, he lost his wallet."}]},{"t":"كيف يصاغ الظرف How adverbs are formed","pg":37,"key":"في معظم الحالات نضيف ly الى نهاية الصفة لتكوين الظرف","p":["بعض الظروف له نفس صيغة الصفة (أي انه صفة وظرف معا)"],"items":[{"h":"الصفة المنتهية ب y","x":"تحول إلى i ثم تضاف ly: easy easily، happy happily."},{"h":"المنتهية ب le أو ible أو able","x":"تحول e إلى y: probable probably، gentle gently."},{"h":"المنتهية ب ic","x":"تضاف ally: basic basically، والشاذة public publicly."},{"h":"صفة وظرف معا","x":"It is a fast car. / He drives very fast."},{"h":"good و well","x":"He is a good student. / He studies well."}]},{"t":"ظروف الكيفية والمكان","pg":40,"key":"انتبه الى ان الظرف يجب أن لايوضع بين الفعل والمفعول به","p":["يعتبر موقع الظرف مهم عندما يوجد اكثر من فعل في الجملة"],"items":[{"h":"بعد المفعول به","x":"He ate the chocolate cake greedily."},{"h":"تغير المعنى بالموقع","x":"She quickly agreed to re-type the letter. (موافقتها كانت سريعة) / She agreed to re-type the letter quickly. (اعادة الطباعة كانت سريعة)"},{"h":"here و there","x":"here نحو المتكلم و there بعيدا عنه: Here comes the bus. / Here it is!"},{"h":"towards","x":"حرف جر وليس ظرفا: He walked towards the car."}]},{"t":"ظروف الزمان Adverbs of Time","pg":43,"key":"ظروف الزمان تخبرنا عن زمن حصول الحدث، وكذلك عن مدته وعدد مرات حدوثه","p":["ظروف (عدد المرات) تعبر عن التكرار لحدث، وتقع عادة قبل الفعل الرئيسي و بعد الافعال المساعدة","عندما يقع ظرف التكرار في نهاية الجملة يكون أقوى"],"items":[{"h":"ظروف متى","x":"توضع عادة في نهاية الجملة: I'm going to tidy my room tomorrow."},{"h":"قبل الفعل الرئيسي","x":"I often eat vegetarian food."},{"h":"بعد الفعل المساعد","x":"You must always fasten your seat belt."},{"h":"yet","x":"في الاستفهام والنفي: They haven't met him yet."},{"h":"still","x":"للاستمرارية: I am still hungry."}]},{"t":"ظروف التأكيد والدرجة والاستفهام والوصل","pg":46,"key":"تعبر ظروف التأكيد عن مدى تأكدنا من حدث أو حادث","p":[],"items":[{"h":"التأكيد","x":"He has certainly forgotten the meeting. / He will probably remember tomorrow."},{"h":"الدرجة","x":"The water was extremely cold. / She has almost finished."},{"h":"how بأربع طرق","x":"How did you make this sauce? / How tall are you? / How many people are coming? / How often do you go to London?"},{"h":"ظروف الوصل","x":"That's the restaurant where we met for the first time."}]}],"quiz":[{"q":"Choose the correct sentence.","o":["He ate the chocolate cake greedily.","He ate greedily the chocolate cake.","He greedy ate the chocolate cake.","He ate the chocolate cake very greedy."],"why":"انتبه الى ان الظرف يجب أن لايوضع بين الفعل والمفعول به","pg":40},{"q":"Choose the correct sentence.","o":["You must always fasten your seat belt.","Always you must fasten your seat belt.","You always must fasten your seat belt.","You must fasten always your own seat belt."],"why":"ظروف (عدد المرات) تعبر عن التكرار لحدث، وتقع عادة قبل الفعل الرئيسي و بعد الافعال المساعدة","pg":44},{"q":"ما نوع كلمة well في الجملة He studies well؟","o":["ظرف مأخوذ من الصفة good","صفة بمعنى جيد تصف الفاعل","ظرف تكرار يقع قبل الفعل","حرف جر يحدد مكان الحدث"],"why":"الكلمة well (بصورة جيدة)، هي ظرف للصفة good (جيد).","pg":39},{"q":"أي وصف للفرق بين yet و still صحيح بحسب الكتاب؟","o":["still للاستمرارية وتأتي في المثبت والاستفهام","yet للاستمرارية وتأتي في المثبت والاستفهام","still للنفي والاستفهام فقط وتقع في نهاية الجملة","كلتاهما للنفي وتقعان قبل الفعل الرئيسي"],"why":"أما still فتعبر عن الاستمرارية، وتستخدم في الجمل الاستفهامية والمثبتة","pg":45},{"q":"ماذا يتغير بين She quickly agreed to re-type the letter و She agreed to re-type the letter quickly؟","o":["الحدث الذي يصفه الظرف بالسرعة","زمن الفعل من الماضي إلى المضارع","نوع الكلمة quickly من ظرف إلى صفة","درجة التأكيد في الجملة فقط"],"why":"يعتبر موقع الظرف مهم عندما يوجد اكثر من فعل في الجملة","pg":41}]},{"k":"c5","t":"الضمير pronoun وحالة التملك Possessive Case","q":"كيف تحل الضمائر محل الأسماء، وكيف نعبر عن الملكية؟","essence":"الضمائر وصفات التملك والفارزة العليا","kw":["الضمائر الانعكاسية","ضمائر الإشارة","الفارزة العليا"],"sections":[{"t":"الضمائر الشخصية personal pronouns","pg":49,"key":"الضمير هو كلمة نستخدمها بدلا من اسماء اشخاص او اشياء، لتجنب تكرار اسمائهم، وذلك للاختصار","p":[],"items":[{"h":"ضمائر الفاعل","x":"I, you, he, she, it, we, they: This is my father. He is a teacher."},{"h":"ضمائر المفعول به","x":"me, you, him, her, it, us, them: My mother is kind. Everybody likes her."}]},{"t":"الضمائر الانعكاسية Reflexive Pronouns","pg":50,"key":"تستخدم الضمائر الانعكاسية عندما ينصب تأثير الفعل على نفس فاعله","p":["وهي عبارة عن صيغ مركبة من الضمائر الشخصية مع اضافة self لها"],"items":[{"h":"الانعكاس","x":"He blamed himself. لام نفسه."},{"h":"التوكيد","x":"Mr. Sami himself came here. جاء بنفسه."},{"h":"مع by بمعنى بمفردي","x":"I went by myself."},{"h":"أمثلة","x":"Be careful with the knife. You'll cut yourself. / Our cat washes itself after each meal."}]},{"t":"ضمائر الاشارة The Demonstratives","pg":51,"key":"وتستخدم لبيان مكان الشخص أو الشيء بالنسبة للمتكلم.","p":[],"items":[{"h":"للقريب والبعيد","x":"this و these للقريب، that و those للبعيد."},{"h":"قرب مادي أو نفسي","x":"Who owns that house? / This is a nice surprise!"},{"h":"قبل one","x":"This car looks cleaner than that one."}]},{"t":"صفات التملك وضمائره","pg":117,"key":"صفات التملك تسبق اسم الشيء المملوك، اما ضمائر التملك فتكون مستقلة اي ترد لوحدها بديلا عن الاسم المملوك","p":["ومع ذلك، لاتشير حالة المضاف اليه دائما الى التملك"],"items":[{"h":"الجدول","x":"I My Mine، You Your Yours، He His His، She Her Hers، We Our Ours، They Their Theirs."},{"h":"مثالان","x":"This is my book. / This is mine."},{"h":"مضاف إليه بلا تملك","x":"children's songs أغاني معدة للأطفال، و Sameer's paintings لوحات رسمها سمير."}]},{"t":"الفارزة العليا Apostrophe وحرف الجر of","pg":119,"key":"نستخدم (of) عندما يكون المضاف والمضاف اليه غير عاقل","p":["عندما يكون هناك اكثر من اسم، نضع ('s) بعد الاسم الثاني."],"items":[{"h":"الاسم المفرد","x":"Ahmed’s book."},{"h":"الاسم الجمع","x":"اما اذا كان الاسم جمع، نضيف الفارزه فقط بدون (s): My brothers’ rooms."},{"h":"الجمع الشاذ","x":"The women’s cars."},{"h":"أكثر من اسم","x":"Nada and Hani’s house."},{"h":"غير العاقل","x":"The door of the car. ويستثنى ما له أهمية كبيرة: The sun's light is necessary for plants."},{"h":"المحلات والعيادات","x":"the dentist's، the chemist's: I've got an appointment at the dentist's at eleven o'clock."}]}],"quiz":[{"q":"Nada and Hani own one house together. Choose the correct form.","o":["Nada and Hani's house","Nada's and Hani's house","Nada and Hanis' house","Nada and Hani house's"],"why":"عندما يكون هناك اكثر من اسم، نضع ('s) بعد الاسم الثاني.","pg":119},{"q":"The rooms belong to my brothers. Choose the correct form.","o":["My brothers' rooms","My brother's rooms","My brothers's rooms","My brothers rooms'"],"why":"اما اذا كان الاسم جمع، نضيف الفارزه فقط بدون (s)","pg":119},{"q":"متى نستخدم الضمير الانعكاسي كما في He blamed himself؟","o":["حين ينصب تأثير الفعل على فاعله","حين يقع الضمير بعد حرف الجر دائما","حين نشير إلى شخص بعيد عن المتكلم","حين نريد تجنب تكرار اسم المفعول"],"why":"تستخدم الضمائر الانعكاسية عندما ينصب تأثير الفعل على نفس فاعله","pg":50},{"q":"متى نستخدم of بدلا من الفارزة العليا للتعبير عن الإضافة؟","o":["حين يكون المضاف والمضاف إليه غير عاقل","حين يكون الاسم جمعا منتهيا بحرف s أو es","حين يتكون الاسم من كلمتين أو أكثر","حين يشترك شخصان في ملكية شيء واحد"],"why":"نستخدم (of) عندما يكون المضاف والمضاف اليه غير عاقل","pg":120},{"q":"ماذا تفيد صيغة المضاف إليه في Sameer's paintings بحسب الكتاب؟","o":["أنها لوحات رسمها سمير","أن سمير يملك اللوحات حتما","أنها لوحات معدة لسمير","أنها لوحات في محل سمير"],"why":"في هذا المثال، سمير قد لايملك اللوحات، فالعبارة تشير فقط الى انها لوحات رسمت من قبله.","pg":118}]},{"k":"c6","t":"اداة الربط Conjunction وصيغة التعجب والمحددات Determiners","q":"كيف نربط الجمل، ومتى نستخدم a و an و few و some و any؟","essence":"أدوات الربط والتعجب والمحددات","kw":["أدوات الربط","أدوات النكرة","some و any"],"sections":[{"t":"ادوات الربط Conjunction","pg":52,"key":"وهي الادوات التي تربط كلمتين او عبارتين مع بعض","p":["وهي ادوات مزدوجة وتعمل كازواج لتساوي بين فقرتين، فاذا اعقب الجزء الاول اسم فلابد ان يعقب الجزء الثاني اسم ايضا"],"items":[{"h":"المنسقة Coordinating","x":"and, but, or: He works quickly but accurately."},{"h":"المتلازمة Correlative","x":"either...or, neither...nor, both...and: You can either walk to school or take the bus."},{"h":"التابعة Subordinating","x":"تربط الجملة التابعة بالرئيسية: Although he is very old, he goes jogging every morning."}]},{"t":"صيغة التعجب interjection","pg":54,"key":"وهو كلمة تعبر عن شعور مفاجيء أو قوي","p":["والتعبير التعجبي لايمثل جزءا من الجملة، بل يعد جملة قائمة بذاتها"],"items":[{"h":"أمثلة شائعة","x":"Wow! / What a pity! / Well done! / Good luck! / Look out!"},{"h":"علامة التعجب","x":"تستخدم بعد عبارات التعجب، وفي التعبير عن أي انفعال قوي، وفي النداء."}]},{"t":"المحددات Determiners","pg":93,"key":"توضع a قبل الاسماء التي تبدأ بحرف صحيح، وتوضع an قبل الاسماء التي تبدأ بحرف علة","p":["تختلف المحددات عن الضمائر بكونها تتبع باسم"],"items":[{"h":"أداة التعريف the","x":"تستخدم قبل المفرد والجمع: The boys are playing football."},{"h":"a و an","x":"This is a book / This is an orange."},{"h":"المحددات الخاصة","x":"the، وأسماء الإشارة، وصفات التملك: These apples are rotten."},{"h":"either و neither","x":"I've got tea and coffee, so you can have either. / Neither of the students were listening."}]},{"t":"few و little و a few و a little","pg":154,"key":"نستخدم few قبل الاسماء الجمع و little قبل الاسماء المفردة الغير معدودة","p":["a few و a little (مع اداة النكرة a) لها نفس معنى some (بعض)"],"items":[{"h":"المعنى السلبي","x":"few students understood it. لم يفهم الكثير من الطلبة الدرس."},{"h":"المعنى الإيجابي","x":"a few students understood it. بعض الطلبة فهموا الدرس."},{"h":"في الكلام العامي","x":"يفضل not many و not much و only a few: We haven't got much time."}]},{"t":"some و any و enough","pg":155,"key":"نستخدم some (بعض) عادة مع الجمل المثبتة","p":["ولكن اذا كنا نتوقع او نرغب بان يجيب الآخر بنعم، نستخدم some (في العروض offers)"],"items":[{"h":"any في النفي والاستفهام","x":"I have not bought any bread. / Have you bought any apples?"},{"h":"any بعد never و without و hardly","x":"We never go anywhere. / There’s hardly anyone here."},{"h":"some في العروض","x":"Would you like some biscuits?"},{"h":"enough","x":"Yes, we have enough cakes to sell today. / I think you have worked hard enough to receive a pay rise."}]}],"quiz":[{"q":"Choose the correct sentence.","o":["Huda wants to buy an umbrella.","Huda wants to buy a umbrella.","Huda wants to buy umbrella.","Huda wants to buy one umbrellas."],"why":"توضع a قبل الاسماء التي تبدأ بحرف صحيح، وتوضع an قبل الاسماء التي تبدأ بحرف علة","pg":93},{"q":"Which sentence says that some students understood the lesson?","o":["A few students understood it.","Few students understood it.","Little students understood it.","A little students understood it."],"why":"a few و a little (مع اداة النكرة a) لها نفس معنى some (بعض)","pg":154},{"q":"لماذا جاءت some في السؤال Would you like some biscuits? مع أن any هي الأصل في الأسئلة؟","o":["لأنه عرض نرغب أن يجاب عنه بنعم","لأن biscuits اسم غير معدود دائما","لأن السؤال جاء بصيغة الماضي البسيط","لأن any لا تأتي مع الأسماء الجمع"],"why":"ولكن اذا كنا نتوقع او نرغب بان يجيب الآخر بنعم، نستخدم some (في العروض offers)","pg":161},{"q":"في الأدوات المتلازمة مثل either...or، إذا جاء بعد الجزء الأول اسم فماذا يجب بعد الجزء الثاني؟","o":["أن يأتي بعده اسم كذلك","أن يأتي بعده فعل مضارع","أن تأتي بعده صفة مقارنة","أن يأتي بعده ضمير فاعل"],"why":"فاذا اعقب الجزء الاول اسم فلابد ان يعقب الجزء الثاني اسم ايضا","pg":53},{"q":"لماذا جاءت any في الجملة المثبتة There’s hardly anyone here؟","o":["لأنها وقعت بعد كلمة hardly","لأن hardly تجعل الجملة استفهامية","لأن hardly لا تأتي إلا مع الجمع","لأن hardly ظرف مكان يتطلبها"],"why":"نستخدم some عادة في الجمل المثبتة، ولكن بعد never و without و hardly نستخدم any","pg":160}]},{"k":"c7","t":"حروف الجر Prepositions","q":"كيف نختار حرف الجر المناسب للوقت والمكان والحركة؟","essence":"حروف الجر للوقت والمكان والحركة","kw":["at و on و in","to و into و by","الكلمات مع حروف الجر"],"sections":[{"t":"ماهو حرف الجر؟","pg":55,"key":"حرف الجر هو الذي يربط الاسماء والضمائر والعبارات بالكلمات الاخرى في الجملة","p":["يشير حرف الجر عادة الى علاقة زمانية او مكانية او منطقية لمفعوله مع بقية الجملة"],"items":[{"h":"أمثلة","x":"The book is on the table. / The book is beside the table. / She read the book during class."},{"h":"وظيفة العبارة","x":"The children climbed the mountain without fear. وعبارة without fear تؤدي وظيفة ظرف."}]},{"t":"حروف الجر للوقت At/on/in","pg":57,"key":"لانستخدم at/on/in قبل last / next / this / every","p":["لايمكنك أن تقول 'in the end of ……'"],"items":[{"h":"at","x":"لأوقات اليوم: at 5 o'clock, at midnight، وفي at night و at the weekend."},{"h":"on","x":"للأيام والتواريخ: on Friday, on my birthday."},{"h":"in","x":"للفترات الطويلة: in October, in 1968, in the morning."},{"h":"next دون حرف جر","x":"I'll see you next Friday."},{"h":"on time و in time","x":"on time في الوقت المحدد: Be on time. Don't be late. / in time مبكر بما يكفي: Will you be home in time for dinner?"},{"h":"at the end و in the end","x":"At the end of the concert, there was great applause. / In the end we sold it."}]},{"t":"حروف الجر للمكان In/at/on","pg":61,"key":"المعتاد استخدام in مع المدن والبلدات والقرى","p":[],"items":[{"h":"in","x":"in a room, in a garden: When we were in Italy, we spent a few days in Venice."},{"h":"at","x":"at the bus stop, at the door: Write your name at the top of the page."},{"h":"on","x":"on the wall, on the floor: There is a label on the bottle."},{"h":"in bed و at home","x":"Murad isn't up yet. He's still in bed. / I'll be at home all evening."},{"h":"وسائط النقل","x":"on a bus, on a train، و in a car, in a taxi: George arrived in a taxi."}]},{"t":"To/at/in/into و by","pg":67,"key":"نستخدم to (الى) مع الافعال go/come/travel ...الخ، ونذكر بعده مكان أو حدث","p":["نستخدم by متبوعة باسم بدون a / the / my"],"items":[{"h":"to للانتقال","x":"When are your friends returning to Italy?"},{"h":"arrive","x":"arrive in a country / town/city، و arrive at لبقية الأماكن: What time did they arrive at the hotel?"},{"h":"home بلا حرف جر","x":"I'm tired. Let's go home."},{"h":"into و out of","x":"She got out of the car and went into a shop."},{"h":"by للسفر","x":"Layla usually goes to work by bus. ولكن: Did you come here by car or on foot?"},{"h":"by في المبني للمجهول","x":"The programme was watched by millions of people."}]},{"t":"الأسماء والصفات والأفعال مع حروف الجر","pg":74,"key":"The train was late but nobody knew the reason for the delay.","p":[],"items":[{"h":"اسم مع حرف جر","x":"a solution to the problem، an increase in the number of road accidents."},{"h":"of بعد صفة السلوك","x":"Thank you. It was very nice/kind of you to help me."},{"h":"صفة مع حرف جر","x":"Layla is married to an American. / Are you interested in art? / The city centre was crowded with tourists."},{"h":"explain","x":"Can you explain this word to me? ولا نقول explain me this word."},{"h":"discuss بلا حرف جر","x":"We discussed a lot of things at the meeting."},{"h":"think about و think of","x":"I'll think about it. / That's a good idea. Why didn't I think of that?"}]}],"quiz":[{"q":"Choose the correct sentence.","o":["They arrived on Friday.","They arrived in Friday.","They arrived at Friday.","They arrived in Fridays."],"why":"on : للايام والتواريخ","pg":57},{"q":"Choose the correct sentence.","o":["I'll see you next Friday.","I'll see you on next Friday.","I'll see you at next Friday.","I'll see you in next Friday."],"why":"لانستخدم at/on/in قبل last / next / this / every","pg":58},{"q":"Choose the correct sentence.","o":["Can you explain this word to me?","Can you explain me this word?","Can you explain this word me?","Can you explain for me this word?"],"why":"Can you explain this word to me? (ولا نقول 'explain me this word')","pg":81},{"q":"ما الفرق بين on time و in time بحسب الكتاب؟","o":["الأولى في الموعد بالضبط والثانية مبكر بما يكفي","الأولى مبكر بما يكفي والثانية في الموعد بالضبط","الأولى للمستقبل القريب والثانية للماضي القريب","لا فرق بينهما ويجوز استعمال كل منهما مكان الأخرى"],"why":"on time = punctual في الوقت المحدد، دقيق","pg":59},{"q":"لماذا يصح by car ولا يصح by my car بحسب الكتاب؟","o":["لأن الاسم بعد by يأتي مجردا بلا محدد","لأن by لا تستعمل مع السيارات مطلقا","لأن by خاصة بوسائط النقل العامة فقط","لأن by لا تأتي إلا في جمل المبني للمجهول"],"why":"نستخدم by متبوعة باسم بدون a / the / my","pg":72}]},{"k":"c8","t":"الافعال المركبة Phrasal verbs وتكوين السؤال والتعبير عن الوقت","q":"كيف نستخدم الأفعال المركبة، ونكوّن الأسئلة، ونخبر عن الوقت؟","essence":"الأفعال المركبة والأسئلة والوقت وتعبيرات شائعة","kw":["الأفعال المركبة","تكوين السؤال","الوقت"],"sections":[{"t":"الافعال المركبة Phrasal verbs","pg":96,"key":"هذه الافعال هي أفعال مركبة (وهي أفعال يضاف اليها ظرف أو حرف جر فيغير معناها)","p":["اذا كان المفعول به ضمير مثل it / them / me / him ...الخ، فتكون للمفعول به حالة واحدة فقط"],"items":[{"h":"معنى خاص","x":"Sorry I'm late. The car broke down. / Look out! There's a car coming."},{"h":"يتبعها حرف جر","x":"Are you looking forward to your holiday?"},{"h":"موقع المفعول به","x":"I turned off the light. / I turned the light off."},{"h":"مع الضمير","x":"I turned it off. ولا نقول I turned off it."}]},{"t":"تكوين السؤال Questions","pg":98,"key":"لتكوين السؤال: نضع الفعل المساعد قبل الفاعل في بداية السؤال.","p":["لايكفي ان نقول \"نعم\" أو \"لا\" عند الجواب، لان ذلك سيكون فظا بعض الشيء"],"items":[{"h":"أسئلة be","x":"Are you from Iraq? Yes, I am."},{"h":"أسئلة have","x":"Have you got a camera? Yes, I have. / Do you have a camera? Yes, I do."},{"h":"المضارع البسيط","x":"Does Ahmed play football? No, he doesn’t."},{"h":"الماضي البسيط","x":"Did Majid play tennis? Yes, he did."},{"h":"السؤال عن الفاعل والمفعول به","x":"Who phoned Jalal? بلا فعل مساعد، و Who did Jalal phone? بفعل مساعد."}]},{"t":"التعبير والسؤال عن الوقت","pg":103,"key":"حرف الجر المستخدم مع الساعات هو (at)","p":["كلمة (past) بالعربية معناها (و) عند استخدامها مع الساعة"],"items":[{"h":"السؤال","x":"What’s the time? / Excuse me, could you tell me the time?"},{"h":"past و to","x":"It’s a quarter past three. الساعة الثالثه والربع / It's ten to three. الساعة الثالثه الا عشر دقائق."},{"h":"am و pm","x":"am قبل الظهر و pm بعد الظهر."},{"h":"الطرق الثلاث","x":"الاعتيادية، والشبه رقمية مثل Six thirty am، والرقمية مثل Fifteen fifteen hours."}]},{"t":"There is / are و It is / they are","pg":153,"key":"نستخدم there is/are للتحدث عن شيء لاول مرة، للقول بانه موجود","p":["ومع ذلك لانختصر there are"],"items":[{"h":"there ثم it","x":"There’s a really nice café next door to our apartment block. It’s famous for its cream cakes."},{"h":"it's للوقت والمسافة والطقس","x":"What time is it? It’s half past four. / It’s hot today."},{"h":"الاختصار","x":"There’s a large kitchen in my apartment. ولا نقول There’re two bathrooms in my house."}]},{"t":"have و have got والأفعال go و play و do مع الرياضة","pg":157,"key":"نستخدم have و have got بنفس المعنى","p":["اذا لم نتحرك من مكان لآخر بل نحرك اذرعنا وسيقاننا عند ممارستها"],"items":[{"h":"الملكية والإلزام","x":"I have a book, I have got a book / I have to go now, I have got to go now."},{"h":"لا تستخدم have got","x":"في الماضي: I had a book، وفي النشاطات: I have a shower."},{"h":"play","x":"مع الرياضات التي تستخدم فيها الكرة: football, tennis, golf."},{"h":"go","x":"إذا تحركنا من مكان إلى آخر: jogging, swimming, climbing."},{"h":"do","x":"gymnastics, judo, karate, yoga."}]}],"quiz":[{"q":"Choose the correct sentence.","o":["I turned it off.","I turned off it.","I off turned it.","I turned it to off."],"why":"اذا كان المفعول به ضمير مثل it / them / me / him ...الخ، فتكون للمفعول به حالة واحدة فقط","pg":97},{"q":"Choose the correct sentence.","o":["I do karate every week.","I play karate every week.","I go karate every week.","I make karate every week."],"why":"اذا لم نتحرك من مكان لآخر بل نحرك اذرعنا وسيقاننا عند ممارستها","pg":157},{"q":"Choose the correct sentence.","o":["There are two bathrooms in my house.","There're two bathrooms in my house.","There have two bathrooms in my house.","There is two bathrooms in my house."],"why":"ومع ذلك لانختصر there are","pg":154},{"q":"لماذا لا يحتاج السؤال Who phoned Jalal? إلى فعل مساعد؟","o":["لأن السائل يسأل فيه عن الفاعل","لأن السائل يسأل فيه عن المفعول به","لأن الفعل phone فعل ناقص لا يتغير","لأن الماضي البسيط لا يقبل did أبدا"],"why":"السؤال عن الفاعل (لانحتاج الى فعل مساعد)","pg":103},{"q":"ما معنى It’s a quarter to three؟","o":["الساعة الثالثة إلا ربعا","الساعة الثالثة والربع","الساعة الثانية إلا ربعا","الساعة الثالثة وخمس وأربعون"],"why":"كلمة (to) بالعربية معناها (الا) عند استخدمها مع الساعة","pg":104}]},{"k":"c9","t":"أزمنة الافعال Verb Tenses: أزمنة المضارع","q":"متى نستخدم كل زمن من أزمنة المضارع؟","essence":"المضارع البسيط والمستمر والتام والتام المستمر","kw":["المضارع البسيط","المضارع التام","since و for"],"sections":[{"t":"المضارع البسيط Present simple","pg":121,"key":"نستخدم المضارع البسيط للتكلم عن أشياء بشكل عام","p":["تذكر ان تضيف (s) للفعل المضارع بعد he/she/it او أي اسم مفرد."],"items":[{"h":"حقائق وعادات","x":"Nurses look after patients in hospitals. / The earth goes round the sun."},{"h":"do و does","x":"What does this word mean? ولا نقول What means this word?"},{"h":"عدد المرات","x":"I get up at 8 o'clock every morning."},{"h":"الوعد والاقتراح","x":"I promise I won't be late. / I suggest that you ..."}]},{"t":"المضارع المستمر Present continuous","pg":123,"key":"المضارع المستمر يعني: انا في وسط عمل هذا الشيء: لقد بدأت القيام به ولم انته منه بعد.","p":["فالحدث يجري غالبا في وقت التكلم"],"items":[{"h":"التكوين","x":"am/is/are + v.ing: I am driving / he is working."},{"h":"وقت التكلم","x":"Please don't make so much noise. I'm working."},{"h":"ليس بالضرورة وقت التكلم","x":"Samira wants to work in Italy, so she is learning Italian."},{"h":"تغيرات جارية","x":"The population of the world is rising very fast."}]},{"t":"ملاحظات هامة: الأفعال الوصفية","pg":125,"key":"نستخدم ازمنة الاستمرار فقط للنشاطات والحوادث","p":[],"items":[{"h":"أفعال لا تأتي مستمرة","x":"like love hate want need prefer know understand believe remember: I'm hungry. I want something to eat."},{"h":"think","x":"What do you think will happen? / You look serious. What are you thinking about?"},{"h":"have بمعنى يملك","x":"We have a nice room in the hotel. ولكن: We're having a great time."},{"h":"being","x":"He is being selfish يتصرف بأنانية الآن، و He is very selfish أناني بشكل عام."}]},{"t":"المضارع التام Present perfect","pg":127,"key":"نستخدم المضارع التام للتعبير عن حدث تم في الماضي ونتائجه مشاهدة الآن، مع وجود تواصل مع الوقت الحالي","p":["نستخدم المضارع التام لإعطاء معلومات جديدة أو للإعلان عن حادث جديد."],"items":[{"h":"التكوين","x":"have/has + past participle: I've lost it."},{"h":"just و already و yet","x":"I've just had lunch. / He's already gone. / I haven't posted it yet."},{"h":"فترة مستمرة إلى الآن","x":"Have you ever been to China? / I haven't eaten anything since breakfast."},{"h":"أول مرة","x":"It's the first time he has driven a car."},{"h":"When و How long","x":"When did it start raining? ماض بسيط، و How long has it been raining? مضارع تام."}]},{"t":"المضارع التام المستمر Present perfect continuous","pg":133,"key":"نستخدم المضارع التام المستمر لحدث (توقف مؤخرا) أو (توقف قبل قليل)، مع وجود تواصل مع الوقت الحالي","p":[],"items":[{"h":"التكوين","x":"have/has been + v.ing: I have been waiting."},{"h":"أثر ظاهر الآن","x":"You're out of breath. Have you been running?"},{"h":"مع how long و for و since","x":"It has been raining for two hours."},{"h":"حدث مستمر","x":"I've been learning English for a long time. ولا نقول I am learning."}]},{"t":"Been و Gone و Since و For","pg":152,"key":"تعني been الذهاب الى مكان والعودة منه","p":["since تأتي بعدها (بداية فترة زمنية) نعرف أولها ولا نعرف متى تنتهي","for تأتي بعدها (فترة زمنية محددة) لا نعرف متى بدأت ولا متى انتهت"],"items":[{"h":"been","x":"I have been to Jordan twice."},{"h":"gone","x":"Nada has gone to school. ندى ذاهبة إلى المدرسة أو هي هناك بالفعل."},{"h":"since","x":"Samira has been in hospital since Monday."},{"h":"for","x":"Suha has been married for ten years."},{"h":"for مع الماضي البسيط","x":"We lived here for ten years. لم نعد نعيش هنا، و We have lived here for ten years. ما زلنا نعيش هنا."}]}],"quiz":[{"q":"Choose the correct sentence.","o":["Please don't make so much noise. I'm working.","Please don't make so much noise. I work.","Please don't make so much noise. I'm work.","Please don't make so much noise. I have working."],"why":"فالحدث يجري غالبا في وقت التكلم","pg":123},{"q":"Choose the correct sentence.","o":["Samira has been in hospital since Monday.","Samira has been in hospital for Monday.","Samira has been in hospital from Monday.","Samira has been in hospital during Monday."],"why":"since تأتي بعدها (بداية فترة زمنية) نعرف أولها ولا نعرف متى تنتهي","pg":156},{"q":"Choose the correct sentence.","o":["It's the first time he has driven a car.","It's the first time he drives a car.","It's the first time he is driving the car.","It's the first time he drove a car."],"why":"It's the first time he has driven a car. (لا يجوز ان نقول 'drives')","pg":131},{"q":"لماذا لا نقول I'm wanting something to eat؟","o":["لأن want لا تأتي في أزمنة الاستمرار","لأن want فعل ناقص لا يقبل الإضافات","لأن المضارع المستمر خاص بالمستقبل وحده","لأن something تتطلب الماضي البسيط"],"why":"نستخدم ازمنة الاستمرار فقط للنشاطات والحوادث","pg":125},{"q":"قيل Jalal is away on holiday. He has gone to Spain. فأين جلال الآن بحسب الكتاب؟","o":["هناك الآن أو في طريقه إليها","عاد منها إلى بيته قبل قليل فقط","زارها مرة واحدة في حياته","لم يسافر إليها حتى الآن"],"why":"تعني gone الذهاب الى مكان وعدم العودة لحد الآن","pg":152}]},{"k":"c10","t":"أزمنة الماضي وزمن المستقبل Future tense","q":"كيف نعبر عن الماضي بدرجاته، وعن المستقبل بصيغه المختلفة؟","essence":"الماضي بأزمنته والمستقبل و used to","kw":["الماضي التام","will و going to","used to"],"sections":[{"t":"الماضي البسيط Past simple","pg":134,"key":"يستخدم الماضي البسيط للتعبير عن حدث تم في الماضي.","p":[],"items":[{"h":"القياسية","x":"I worked in a shop two days ago."},{"h":"الشاذة","x":"write wrote، see saw، go went: They went to the zoo last week."},{"h":"did و didn't","x":"Did you go out last night? / They didn't invite her to the party, so she didn't go."},{"h":"was و were بلا do","x":"Was the weather good when you were on holiday?"}]},{"t":"الماضي المستمر Past continuous","pg":136,"key":"نستخدم الماضي المستمر لنقول ان شخصا ما كان في وسط عمل شيء في وقت معين","p":["وغالبا ما نستخدم الماضي البسيط والماضي المستمر سوية لنقول بان شيئا ما حدث في وسط شيء آخر."],"items":[{"h":"في وسط حدث","x":"I was walking home when I met Dave."},{"h":"حدث تام","x":"I walked home after the party last night."},{"h":"الفرق في المعنى","x":"When Huda arrived, we were having dinner. بدأنا قبل وصولها / When Huda arrived, we had dinner. وصلت أولا ثم تناولنا العشاء."},{"h":"أفعال لا تأتي مستمرة","x":"We knew each other well. ولا نقول we were knowing."}]},{"t":"الماضي التام والماضي التام المستمر","pg":138,"key":"هذه هي نقطة بداية القصة. وبعدها، ان اردنا التحدث عن اشياء حدثت قبل هذا الوقت عندها سنستخدم الماضي التام (had ... )","p":[],"items":[{"h":"التكوين","x":"had + past participle: When Suha arrived at the party, Hani had already gone home."},{"h":"قبل ذلك الوقت","x":"I didn't know who she was. I'd never seen her before."},{"h":"التام المستمر","x":"had been + v.ing: I was very tired when I arrived home. I'd been working hard all day."},{"h":"لبرهة قبل حدث آخر","x":"Kareem gave up smoking two years ago. He'd been smoking for 30 years."}]},{"t":"المستقبل ب will و shall","pg":141,"key":"نستخدم I'll (I will) عندما نقرر عمل شيء ما في وقت التكلم (قرار مفاجيء)","p":["لا تستخدم will للتعبير عما خططت وقررت لفعله مسبقا."],"items":[{"h":"القرار المفاجئ","x":"Oh, I've left the door open. I'll go and shut it."},{"h":"العرض والوعد","x":"That bag looks heavy. I'll help you with it. / I'll pay you back on Friday."},{"h":"الرفض ب won't","x":"The car won't start."},{"h":"Shall I و Shall we","x":"Shall I open the window? / Where shall we go this evening?"},{"h":"التكهن","x":"Don't worry about the exam. I'm sure you'll pass."}]},{"t":"استخدام going to وأزمنة المضارع للمستقبل","pg":145,"key":"تستخدم going to لعمل شيء ما، قررت عمله مسبقا أو نويت ان تفعله","p":["عندما نقول 'something is going to happen'، أي نتوقع حدوث شيء، لان الوضع الحالي هو الذي يجعلنا نعتقد ذلك"],"items":[{"h":"نية مسبقة","x":"Samia and I have decided to have a party. We're going to invite lots of people."},{"h":"دليل حاضر","x":"Look at those black clouds! It's going to rain."},{"h":"was going to","x":"He was going to do it but he changed his mind."},{"h":"المضارع المستمر للخطط","x":"I'm meeting her at the station."},{"h":"المضارع البسيط للمواعيد الثابتة","x":"The train leaves Plymouth at 11.30 and arrives in London at 14.45."}]},{"t":"المستقبل المستمر والتام واستخدام would و used to","pg":150,"key":"used to تكون بصيغة (ماضي) فقط، فليس لها صيغة مضارع","p":["ولكن من غير الجائز استخدام would بدلا من used to في موقف متصل كان قائما في الماضي"],"items":[{"h":"المستقبل المستمر","x":"This time next week I'll be lying on a beach or swimming in the sea."},{"h":"المستقبل التام","x":"The film will already have started by the time we get to the cinema."},{"h":"used to","x":"This building is now a furniture shop. It used to be a cinema."},{"h":"would للعادة المتكررة","x":"When I was a student, I would go to the cinema every Sunday."},{"h":"I am used to doing","x":"I am used to living alone. بمعنى اعتدت على الوحدة."}]}],"quiz":[{"q":"Which sentence means dinner had already started before Huda came?","o":["When Huda arrived, we were having dinner.","When Huda arrived, we had dinner.","When Huda arrived, we have had dinner.","When Huda arrived, we are having our dinner."],"why":"(يعني: كنا قد بدأنا تناول طعام العشاء قبل وصول هدى)","pg":137},{"q":"Choose the correct sentence.","o":["When Suha arrived at the party, Hani had already gone home.","When Suha arrived at the party, Hani has already gone home.","When Suha arrived at the party, Hani already goes home.","When Suha arrived at the party, Hani was already going to home."],"why":"ان اردنا التحدث عن اشياء حدثت قبل هذا الوقت عندها سنستخدم الماضي التام","pg":138},{"q":"Choose the correct offer.","o":["That bag looks heavy. I'll help you with it.","That bag looks heavy. I help you with it.","That bag looks heavy. I'm helping you with it.","That bag looks heavy. I helped you with it."],"why":"That bag looks heavy. I'll help you with it. (لا يجوز ان نقول 'I help')","pg":142},{"q":"لماذا نقول Look at those black clouds! It's going to rain ولا نقول it will rain؟","o":["لأن الوضع الحالي يجعلنا نتوقع حدوثه","لأن المتكلم قرر ذلك في وقت التكلم","لأن المطر حدث تكرر كثيرا في الأيام الماضية","لأن will لا تستعمل مع الطقس أبدا"],"why":"عندما نقول 'something is going to happen'، أي نتوقع حدوث شيء، لان الوضع الحالي هو الذي يجعلنا نعتقد ذلك","pg":146},{"q":"ما معنى I am used to living alone بحسب الكتاب؟","o":["أعيش وحيدا ولا أجد ذلك غريبا","عشت وحيدا قديما ولم أعد كذلك","كنت أعيش وحيدا حين حدث أمر ما","سأعيش وحيدا ابتداء من الغد"],"why":"(أي: اعيش وحيدا وانا لا اجد ذلك غريبا أو جديدا لأني عشت على هذا الحال لفترة من الزمن)","pg":165}]},{"k":"c11","t":"الجمل الشرطية Conditional sentences وصيغة ال ing","q":"كيف نبني الجمل الشرطية، ومتى نستخدم اسم الفاعل واسم المصدر؟","essence":"أنواع الشرط واسم الفاعل واسم المصدر","kw":["الجمل الشرطية","اسم الفاعل","اسم المصدر"],"sections":[{"t":"الجملة الشرطية صفر والنوع الاول","pg":108,"key":"وهو تركيب يستخدم للتحدث عن حقائق عامة، واشياء صحيحة دائما، كالحقائق العلمية ...الخ","p":["وهو تركيب يستخدم للتحدث عن اشياء محتملة الحدوث في الحاضر أو المستقبل"],"items":[{"h":"صفر: If + مضارع بسيط، مضارع بسيط","x":"If you heat the water to 100 degrees, it boils."},{"h":"when بدل if","x":"أغلب جمل الشرط صفر تعطي المعنى ذاته إذا استخدمت when."},{"h":"الأول: If + مضارع بسيط، مستقبل بسيط","x":"If you study hard, you will pass the test."}]},{"t":"النوع الثاني والنوع الثالث","pg":109,"key":"فغالبا يستخدم للتعبير عن النقد والتحسر","p":["وهو تركيب يستخدم للتحدث عن حالات غير حقيقية في الماضي (حالات لم تحدث في الماضي)"],"items":[{"h":"الثاني: If + ماضي بسيط، would","x":"If I had a million dollars, I would buy a big house."},{"h":"الثالث: If + ماضي تام، would have + p.p.","x":"If I had studied harder, I would have passed the exam."},{"h":"الفارزة","x":"تستخدم إذا جاءت جملة if أولا: You will pass the test if you study hard."}]},{"t":"اسم الفاعل The present participle","pg":166,"key":"صيغة ال ing للفعل قد تكون اسم المصدر أو اسم الفاعل.","p":["فالمصدر يشير الى حدث مكتمل ولكن اسم الفاعل يشير الى حدث غير مكتمل أو جزء من حدث"],"items":[{"h":"صيغة الاستمرار","x":"he was singing / they have been walking."},{"h":"بعد أفعال الحركة","x":"She went shopping / She came running towards me."},{"h":"بعد أفعال الحواس","x":"I heard Layla singing. / I heard Layla sing."},{"h":"صفة","x":"It was an amazing film."},{"h":"بدل عبارة السبب","x":"Feeling hungry, he went into the kitchen and opened the fridge."}]},{"t":"اسم المصدر The gerund","pg":170,"key":"ويجب استخدام اسم المصدر عندما يأتي الفعل بعد حرف الجر","p":["فمن المهم معرفة ان to هي حرف جر في هذه الحالات، كما انها يجب ان تكون متبوعة ب (اسم مصدر)"],"items":[{"h":"فاعلا للجملة","x":"Flying makes me nervous."},{"h":"بعد حروف الجر","x":"She is good at painting. / We arrived in Madrid after driving all night."},{"h":"بعد الأفعال المركبة","x":"When are you going to give up smoking?"},{"h":"to حرف جر","x":"I look forward to hearing from you soon. / I am used to waiting for buses."},{"h":"الاختبار","x":"إذا استطعت وضع اسم أو الضمير it بعد to فهي حرف جر: I am accustomed to it."}]},{"t":"أفعال يتبعها اسم المصدر","pg":172,"key":"يستخدم اسم المصدر بعد افعال معينة","p":[],"items":[{"h":"قائمة مختارة","x":"admit, avoid, consider, enjoy, finish, imagine, mind, miss, postpone, risk, suggest."},{"h":"admit","x":"Ahmed admitted breaking the window / Ahmed admitted that he had broken the window."},{"h":"prevent","x":"You can't prevent my leaving. / You can't prevent me from leaving."},{"h":"suggest","x":"He suggested going to Glastonbury / He suggested that I should go to New York."},{"h":"أمثلة","x":"I can't imagine living in that big house. / They decided to postpone painting the house until the weather improved."}]}],"quiz":[{"q":"Choose the correct sentence.","o":["If I had a million dollars, I would buy a big house.","If I have a million dollars, I would buy a big house.","If I will have a million dollars, I would buy a big house.","If I had had a million dollars, I would buy a big house."],"why":"وهو تركيب يستخدم للتحدث عن حالات غير حقيقية ليست صحيحة أو ليست ممكنة) في الحاضر أو في المستقبل","pg":109},{"q":"Choose the correct sentence.","o":["I look forward to hearing from you soon.","I look forward to hear from you soon.","I look forward to heard from you soon.","I look forward to be hearing from you soon."],"why":"فمن المهم معرفة ان to هي حرف جر في هذه الحالات، كما انها يجب ان تكون متبوعة ب (اسم مصدر)","pg":171},{"q":"أي أنواع الجمل الشرطية يستخدم غالبا للتعبير عن النقد والتحسر؟","o":["الجملة الشرطية من النوع الثالث","الجملة الشرطية من النوع الثاني وحده","الجملة الشرطية من النوع الأول","الجملة الشرطية من النوع صفر"],"why":"فغالبا يستخدم للتعبير عن النقد والتحسر","pg":110},{"q":"ما الفرق بين I heard Layla singing و I heard Layla sing؟","o":["الأولى لجزء من الغناء والثانية لغنائها كله","الأولى لغنائها كله والثانية لجزء من الغناء","الأولى للماضي البسيط والثانية للمضارع التام","لا فرق بينهما في المعنى ولا في الاستعمال"],"why":"فالمصدر يشير الى حدث مكتمل ولكن اسم الفاعل يشير الى حدث غير مكتمل أو جزء من حدث","pg":167},{"q":"بحسب الكتاب، بماذا يتبع الفعل prevent؟","o":["بصفة تملك أو بمفعول به و from ثم اسم مصدر","بمصدر مع to مباشرة دون مفعول به قبله","بمصدر مجرد بدون to بعد المفعول به","بعبارة that يحذف منها should في كل الأحوال"],"why":"يتبع الفعل Prevent أما بصفة تملك + اسم مصدر أو بمفعول به + from + اسم مصدر","pg":174}]},{"k":"c12","t":"المبني للمجهول Passive voice والكلام المنقول والملاحق","q":"كيف نحول الجملة إلى المبني للمجهول، وننقل كلام غيرنا؟","essence":"المجهول والكلام المنقول والأفعال الشاذة والإملاء","kw":["المبني للمجهول","الكلام المنقول","الأفعال الشاذة"],"sections":[{"t":"متى نستخدم المبني للمجهول؟","pg":175,"key":"نستخدم المبني للمجهول عندما يكون الفاعل (غير مهم) أو (غير معروف) في الجملة.","p":["فلايهمنا من نظفها، بقدر ماتهمنا عملية التنظيف، أو ربما لانعرف من نظفها."],"items":[{"h":"المعلوم والمجهول","x":"Ahmed cleaned the room. / The room was cleaned."},{"h":"فاعل مجهول","x":"A car was stolen."},{"h":"ذكر الفاعل ب by","x":"The room was cleaned by my grandfather."}]},{"t":"كيف نكون المبني للمجهول؟","pg":176,"key":"صيغة المبني للمجهول هي: الفاعل تتبعه احد صيغ فعل الكينونة (be) ثم التصريف الثالث للفعل.","p":["المفعول به الذي نريد ان (نركز على اهميته)، هو من نضعه الفاعل في جملة المبني للمجهول."],"items":[{"h":"الأزمنة","x":"The door is opened / was opened / has been opened / will be opened by Ahmed."},{"h":"المستمر","x":"The door is being opened by Ahmed."},{"h":"مفعولان","x":"Ahmed was given the book. / The book was given to Ahmed."},{"h":"born","x":"Layla was born in Cairo. ولا يجوز أن نقول I am born."}]},{"t":"الكلام المباشر والكلام الغير مباشر Direct and reported speech","pg":178,"key":"الكلام المباشر يكرر او يقتبس الكلام كما هو","p":["الكلام المنقول يستخدم عادة للتكلم عن الماضي، ولذا من الطبيعي تغيير زمن الكلام."],"items":[{"h":"say و tell","x":"He said that he was tired. / He told me that he was tired."},{"h":"تحول الأزمنة","x":"She said, \"I am tired.\" She said that she was tired. / \"I have been to Spain\", he told me. He told me that he had been to Spain."},{"h":"ما لا يتغير","x":"might, could, would, should, ought to: She said that she might bring a friend to the party."}]},{"t":"تغيير الوقت والمكان والأسئلة والأوامر","pg":181,"key":"عند التحويل من الكلام المباشر الى الكلام المنقول نغير مفردات الوقت والمكان","p":["الاسئلة التي تكون اجابتها نعم أو لا: هذا النوع من الاسئلة ينقل باستخدام ask ثم if أو whether ثم عبارة."],"items":[{"h":"الوقت والمكان","x":"Today تصبح that day، Tomorrow تصبح the next day، here تصبح there."},{"h":"سؤال نعم أو لا","x":"\"Do you speak English?\" He asked me if I spoke English."},{"h":"أدوات السؤال","x":"\"What is your name?\" he asked me. He asked me what my name was."},{"h":"الأوامر","x":"\"Get out of the car!\" said the policeman. The policeman ordered him to get out of the car."},{"h":"طلب الأشياء","x":"\"Can I have an apple?\", she asked. She asked for an apple."}]},{"t":"الملاحق: الافعال القياسية والشاذة والإملاء","pg":188,"key":"عندما لاينتهي الماضي البسيط والتصريف الثالث ب ed، مثل (I saw/I have seen)، فيكون الفعل عندها شاذ (غير قياسي).","p":[],"items":[{"h":"الصيغ الثلاث متطابقة","x":"hit hit hit."},{"h":"الماضي والتصريف الثالث متطابقان","x":"tell told told."},{"h":"الصيغ الثلاث مختلفة","x":"wake woke woken."},{"h":"قياسي أو شاذ","x":"learn learned أو learnt، والشاذة شائعة في الإنجليزية البريطانية."},{"h":"مضاعفة الحرف","x":"stop stopping stopped، big bigger biggest، وفي البريطانية travel travelling travelled."},{"h":"ie تصبح y","x":"die dying، lie lying، tie tying."}]}],"quiz":[{"q":"Choose the passive form of: Ahmed has opened the door.","o":["The door has been opened by Ahmed.","The door has opened by Ahmed.","The door was been opened by Ahmed.","The door has being opened by Ahmed."],"why":"صيغة المبني للمجهول هي: الفاعل تتبعه احد صيغ فعل الكينونة (be) ثم التصريف الثالث للفعل.","pg":176},{"q":"Report this: \"I have been to Spain\", he told me.","o":["He told me that he had been to Spain.","He told me that he has been to Spain.","He said to me that he has been to Spain.","He told that he had been to Spain."],"why":"يكون الزمن في الكلام المنقول عادة سابق للزمن في الكلام المباشر","pg":179},{"q":"كيف ننقل سؤالا جوابه نعم أو لا مثل Do you speak English؟","o":["باستخدام ask ثم if أو whether ثم عبارة","باستخدام tell ثم to ثم مصدر الفعل","بإبقاء ترتيب كلمات السؤال وعلامة الاستفهام","باستخدام say ثم that ثم السؤال نفسه"],"why":"الاسئلة التي تكون اجابتها نعم أو لا: هذا النوع من الاسئلة ينقل باستخدام ask ثم if أو whether ثم عبارة.","pg":183},{"q":"أي مجموعة من الأفعال الناقصة لا تتغير في الكلام المنقول؟","o":["might و could و should","will و can و shall و may","can و may و will و must","shall و can و must و will"],"why":"هذه الافعال الناقصة لاتتغير في الكلام المنقول: might, could, would, should, ought to","pg":181},{"q":"متى نستخدم المبني للمجهول بحسب الكتاب؟","o":["حين يكون الفاعل غير مهم أو غير معروف","حين يكون المفعول به ضميرا متصلا بالفعل","حين يكون الفعل لازما بلا مفعول به","حين يكون الحدث في المستقبل فقط"],"why":"نستخدم المبني للمجهول عندما يكون الفاعل (غير مهم) أو (غير معروف) في الجملة.","pg":175}]}],"highlights":[{"x":"لغة عالمية واصبحت من متطلبات الحياة العصرية","pg":4},{"x":"ويمكن الاستفادة منه دون الحاجة للرجوع الى المدرس","pg":4},{"x":"يكون للاسماء المركبة غالبا معنى مختلف عن الكلمات المنفصلة","pg":12},{"x":"المصدر هو الصيغة الاساسية للفعل","pg":13},{"x":"انتبه الى ان الظرف يجب أن لايوضع بين الفعل والمفعول به","pg":40},{"x":"عندما يقع ظرف التكرار في نهاية الجملة يكون أقوى","pg":45},{"x":"فغالبا يستخدم للتعبير عن النقد والتحسر","pg":110},{"x":"نستخدم ازمنة الاستمرار فقط للنشاطات والحوادث","pg":125},{"x":"فأسم المصدر له نفس وظيفة الاسم دائما (برغم كونه يشبه الفعل)","pg":170},{"x":"الكلام المباشر يكرر او يقتبس الكلام كما هو","pg":178}],"concepts":[{"term":"أجزاء الكلام","def":"تتكون الجملة في اللغة الانكليزية من 8 انواع من الكلمات","pg":5},{"term":"الاسماء المركبة","def":"يمكن للكلمات ان تتوحد لتشكيل (اسماء مركبة)، وهذا شائع جدا","pg":10},{"term":"المصدر The Infinitive","def":"المصدر هو الصيغة الاساسية للفعل","pg":13},{"term":"الظرف Adverb","def":"يصف الفعل أو الصفة أو ظرف آخر أو كل الجملة","pg":37},{"term":"ظروف التأكيد","def":"تعبر ظروف التأكيد عن مدى تأكدنا من حدث أو حادث","pg":46},{"term":"الضمير Pronoun","def":"الضمير هو كلمة نستخدمها بدلا من اسماء اشخاص او اشياء، لتجنب تكرار اسمائهم، وذلك للاختصار","pg":49},{"term":"الضمائر الانعكاسية","def":"وهي عبارة عن صيغ مركبة من الضمائر الشخصية مع اضافة self لها","pg":50},{"term":"ادوات الربط Conjunction","def":"وهي الادوات التي تربط كلمتين او عبارتين مع بعض","pg":52},{"term":"صيغة التعجب interjection","def":"وهو كلمة تعبر عن شعور مفاجيء أو قوي","pg":54},{"term":"حرف الجر Preposition","def":"حرف الجر هو الذي يربط الاسماء والضمائر والعبارات بالكلمات الاخرى في الجملة","pg":55},{"term":"الافعال المركبة Phrasal verbs","def":"وهي أفعال يضاف اليها ظرف أو حرف جر فيغير معناها","pg":96},{"term":"الجملة الشرطية صفر","def":"وهو تركيب يستخدم للتحدث عن حقائق عامة، واشياء صحيحة دائما، كالحقائق العلمية ...الخ","pg":108},{"term":"البواديء prefixes","def":"وهي الاحرف التي توضع في بداية الكلمة يؤدي الى تغيير معناها الى الضد احيانا","pg":111},{"term":"اللواحق suffixes","def":"وهي الاحرف التي توضع في نهاية الكلمة","pg":111},{"term":"المضارع المستمر","def":"المضارع المستمر يعني: انا في وسط عمل هذا الشيء: لقد بدأت القيام به ولم انته منه بعد.","pg":123},{"term":"الماضي البسيط","def":"يستخدم الماضي البسيط للتعبير عن حدث تم في الماضي.","pg":134},{"term":"المبني للمجهول Passive voice","def":"نستخدم المبني للمجهول عندما يكون الفاعل (غير مهم) أو (غير معروف) في الجملة.","pg":175},{"term":"الكلام المنقول Reported speech","def":"الكلام المنقول يستخدم عادة للتكلم عن الماضي، ولذا من الطبيعي تغيير زمن الكلام.","pg":179},{"term":"الافعال الشاذة irregular verbs","def":"عندما لاينتهي الماضي البسيط والتصريف الثالث ب ed، مثل (I saw/I have seen)، فيكون الفعل عندها شاذ (غير قياسي).","pg":188}],"links":[{"topic":"أزمنة الأفعال","pg":121},{"topic":"صياغة الأسئلة","pg":98},{"topic":"قراءة الساعة والوقت","pg":103},{"topic":"الإملاء والتهجي","pg":195},{"topic":"المرادفات","pg":199},{"topic":"الكلام المنقول","pg":178},{"topic":"الرياضة","pg":157},{"topic":"الجنسيات والبلدان","pg":226}]};
